class Headers:
    def __init__(self):
        self._data = {}

    def set(self, name, value):
        self._data[name.lower()] = value

    def get(self, name):
        return self._data.get(name.lower())


def handle_request(headers):
    content_type = headers.get("Content-Type")
    auth = headers.get("authorization")
    if content_type != "application/json":
        return {"status": 400, "error": "unsupported content type"}
    if not auth:
        return {"status": 401, "error": "missing credentials"}
    return {"status": 200, "message": "ok", "token": auth}


req = Headers()
req.set("Content-Type", "application/json")
req.set("Authorization", "Bearer abc123")
print(handle_request(req))

req2 = Headers()
req2.set("content-type", "text/plain")
print(handle_request(req2))

resp = Headers()
resp.set("Content-Type", "application/json")
resp.set("Cache-Control", "max-age=3600")
print("Cache-Control:", resp.get("cache-control"))
